// Perform data-driven subcategory refinement for Wires & Cables at source level
PRODUCTS.forEach(p => {
  if (p.category === 'WIRES/CABLES') {
    const sub = (p.subcategory || '').toUpperCase();
    const name = p.name.toUpperCase();
    if (sub.includes('FINOLEX') || name.includes('FINOLEX')) {
      if (
        sub.includes('COMMUNICATION') || 
        sub.includes('POWER') || 
        sub.includes('SUBMERSIBLE') || 
        sub.includes('AUTOMOTIVE') ||
        name.includes('SUBMERSIBLE') ||
        name.includes('COMMUNICATION') ||
        name.includes('POWER')
      ) {
        p.subcategory = 'Finolex ';
      } else {
        p.subcategory = 'Finolex';
      }
    } else if (sub.includes('POLYCAB') || name.includes('POLYCAB')) {
      p.subcategory = 'Polycab';
    } else if (sub.includes('RR') || name.includes('RR ')) {
      p.subcategory = 'RR Firex';
    } else if (sub.includes('HAVELLS') || name.includes('HAVELLS')) {
      p.subcategory = 'Havells';
    } else if (sub.includes('ANCHOR') || name.includes('ANCHOR')) {
      p.subcategory = 'Havells';
    } else {
      p.subcategory = 'Polycab';
    }
  }
});

